//! The UI as data. A `Ui` is everything on screen: a tree of nodes, the data sources the tree
//! binds to, and the keys. It is plain JSON, so a whole UI can be written by hand, generated by
//! an agent, pushed into a running screen and read back out.
//!
//! The world (your notes, prices, logs) is not in here. A node names a source (`bind`), a source
//! says how to fetch the world (a command that prints JSON, or a literal value), and the view
//! reads whatever the runtime last fetched.

use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::BTreeMap;

/// One whole UI.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Ui {
    pub root: Node,
    /// Named data sources, fetched by the runtime and bound to by nodes.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub data: BTreeMap<String, Source>,
    /// Starting values for store entries (`seed`s): each is written only when its entry doesn't
    /// exist yet, so a push never overwrites what the person or another agent wrote.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub store: BTreeMap<String, Value>,
    /// Keys that work everywhere (a focused node's own `keys` win).
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub keys: BTreeMap<String, Action>,
    /// Named colours every node can use, and the screen's own (`bg`, `fg`, `border`, `accent`,
    /// `pos`, `neg`, `hover`).
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub theme: BTreeMap<String, String>,
    /// Callouts, arrows, rings and spotlights over the screen, anchored to nodes and rows
    /// (placed by caretline-layers).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub layers: Vec<LayerSpec>,
    /// Where the focus goes when this UI is pushed (a node id), instead of staying where it was
    /// or going to the first node that takes it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub focus: Option<String>,
    /// The runtime's own status line: the status, else the first problem, else hints. `false`
    /// hides it, so the UI owns every row; `"speed"` adds the speed meter (frames, build time,
    /// messages a second), which is bindable as `$stats` either way.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub status_bar: Option<StatusBar>,
    /// The window's title, a template: its paths name store entries, sources or a list's
    /// selected row (`@id`) as binds do (`"{project.name} · Caption Genius"`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
}

/// `status_bar`: shown or not, or shown with the speed meter.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum StatusBar {
    On(bool),
    Speed,
}

impl Serialize for StatusBar {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        match self {
            StatusBar::On(b) => s.serialize_bool(*b),
            StatusBar::Speed => s.serialize_str("speed"),
        }
    }
}

impl StatusBar {
    pub fn shown(self) -> bool {
        self != StatusBar::On(false)
    }
}

impl<'de> Deserialize<'de> for StatusBar {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        match Value::deserialize(d)? {
            Value::Bool(b) => Ok(StatusBar::On(b)),
            Value::String(s) if s == "speed" => Ok(StatusBar::Speed),
            v => Err(wrong("status_bar is true, false or \"speed\"", &v)),
        }
    }
}

/// A theme: colour `tokens`, styles for the `parts` of components the runtime draws, named
/// `variants` a node can ask for, and the scales parts and styles name: `space` (`s2`),
/// `radius` (`r2`), `depth` (`e1`, shadows), `type` (roles: `body`, `display`) and `fonts`.
/// A part is a short ink (`accent+b`, as in template markup) or a whole style (see `Style`).
/// Themes are the person's or the project's, loaded with `--themes`; a push doesn't change them.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct ThemeSpec {
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub tokens: BTreeMap<String, String>,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub parts: BTreeMap<String, Part>,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub variants: BTreeMap<String, Variant>,
    /// Spacing by name: `"s2": "8px"` (or cells, `1`).
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub space: BTreeMap<String, Len>,
    /// Corner radii by name, in pixels: `"r2": 6`.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub radius: BTreeMap<String, f32>,
    /// Elevations by name, each a list of shadows (a glow is a shadow with no offset).
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub depth: BTreeMap<String, Vec<Shadow>>,
    /// Type roles by name: `"display": {"font": "display", "size": 56, "weight": 800}`.
    #[serde(default, rename = "type", skip_serializing_if = "BTreeMap::is_empty")]
    pub types: BTreeMap<String, TypeRole>,
    /// Fonts by name: a family (`"Inter"`) or a font file (`"fonts/Anton.ttf"`). A type role's
    /// `font` names one, or a family directly.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub fonts: BTreeMap<String, String>,
    /// Reserved for transitions (phase 3): read, kept, not used yet.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub motion: BTreeMap<String, Value>,
}

/// A theme part: a short ink (`"accent+b"`) or a whole style.
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum Part {
    Ink(String),
    Whole(Box<Style>),
}

impl Part {
    /// The part's ink as a spec: itself, or a whole style's colours and modifiers
    /// (`fg+on-panel+b`), for what reads parts as ink.
    pub fn spec(&self) -> String {
        match self {
            Part::Ink(s) => s.clone(),
            Part::Whole(s) => s.spec(),
        }
    }
}

/// A length: cells (`1`), pixels (`"8px"`), or the name of a `space` entry (`"s2"`).
#[derive(Clone, Debug, PartialEq)]
pub enum Len {
    Cells(f32),
    Spec(String),
}

// Whole cells as integers, as they were written.
impl Serialize for Len {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        match self {
            Len::Cells(n) if n.fract() == 0. && n.abs() < 1e9 => s.serialize_i64(*n as i64),
            Len::Cells(n) => s.serialize_f32(*n),
            Len::Spec(t) => s.serialize_str(t),
        }
    }
}

/// One shadow: offset, blur and spread in pixels, and its colour (a token or a colour, with
/// an optional alpha `0`–`1`).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Shadow {
    #[serde(default)]
    pub x: f32,
    #[serde(default)]
    pub y: f32,
    #[serde(default)]
    pub blur: f32,
    #[serde(default)]
    pub spread: f32,
    pub color: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub alpha: Option<f32>,
}

/// A type role: a font (a `fonts` name or a family), size and line height in pixels, a weight
/// (100–900), letter spacing in pixels, whether numbers are tabular, and OpenType features on
/// or off by tag (`{"calt": false, "liga": false}` turns a code font's ligatures off; a number
/// picks an alternate, `{"ss02": 1}`).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct TypeRole {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub font: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub size: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub weight: Option<u16>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub line: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tracking: Option<f32>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub tabular: bool,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty", deserialize_with = "features")]
    pub features: BTreeMap<String, u32>,
}

/// OpenType features by tag (four letters), each `true`, `false` or a number (`1` for on).
fn features<'de, D: serde::Deserializer<'de>>(d: D) -> Result<BTreeMap<String, u32>, D::Error> {
    let mut out = BTreeMap::new();
    for (tag, v) in BTreeMap::<String, Value>::deserialize(d)? {
        if tag.len() != 4 || !tag.is_ascii() {
            return Err(wrong("a font feature's tag is four letters (calt, liga, ss01)", &Value::String(tag)));
        }
        let n = match &v {
            Value::Bool(b) => u32::from(*b),
            Value::Number(n) => n.as_u64().and_then(|n| u32::try_from(n).ok()).ok_or_else(|| wrong("a font feature is true, false or a number", &v))?,
            _ => return Err(wrong("a font feature is true, false or a number", &v)),
        };
        out.insert(tag, n);
    }
    Ok(out)
}

/// A background: a colour, or a gradient between two at an angle (degrees, 180 is top to
/// bottom).
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum Fill {
    Colour(String),
    Gradient {
        from: String,
        to: String,
        #[serde(default = "down")]
        angle: f32,
    },
}

fn down() -> f32 {
    180.
}

impl Fill {
    /// The colour, or where a gradient starts.
    pub fn colour(&self) -> &str {
        match self {
            Fill::Colour(c) => c,
            Fill::Gradient { from, .. } => from,
        }
    }
}

/// A line around a box: its width in pixels, colour, and `solid` (the default), `dashed` or
/// `double`. Written as an object or in short, as a backdrop's border is: `"accent"`,
/// `"2px dashed accent"`.
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct Line {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub style: Option<String>,
}

/// A focus ring: a line `offset` pixels outside the box.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Ring {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub offset: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
}

/// A named look: a style under the node's own, and a border and backdrop when the node has none.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Variant {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub style: Option<Style>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub edge: Option<String>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub border: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub backdrop: Option<Backdrop>,
    /// The style of the node's title.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    /// Parts drawn inside a node wearing it, over the theme's (`row`, `row.selected`,
    /// `scrollbar`): a shelf of cards whose rows look unlike a list of tracks' rows.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub parts: BTreeMap<String, Part>,
}

/// One layer, anchored to a node (`on`) or one of its rows (`row`).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct LayerSpec {
    pub on: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub row: Option<usize>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub text: Option<String>,
    /// Fill `title` and `text` from this source (`"fin.kpi"`), so a callout shows live values.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bind: Option<String>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub arrow: bool,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub ring: bool,
    /// The ring pulses with this period (ms).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pulse: Option<u32>,
    /// Dim everything but the anchor and the box.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub spotlight: bool,
    /// Sides to try, in order: `below`, `above`, `right`, `left`.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub place: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<u16>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub look: Option<Look>,
    /// Who placed it; drawn in the border (`◆ analyst`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub by: Option<String>,
    /// Shown only while this holds, as a node's `when`: a hint that goes once it's been taken.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub when: Option<String>,
}

/// How a layer looks: colours by name or `#rrggbb`, and the border.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Look {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub accent: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fill: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fg: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ring: Option<String>,
    /// `rounded` (default), `double`, `thick` or `plain`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub edge: Option<String>,
}

/// What a list does with a row dropped on one of its rows. Its templates read the row dropped on
/// as a click's do (`{id}`), the row carried as `{$drag.id}` (every carried row's key in
/// `{$drag.keys}`), and which side of it the row goes as `{$drop.side}`: `before` or `after`.
/// `files` takes files dragged in from outside the window (Finder) the same way: let go over a
/// row, or over the list after its last row, it runs with their paths as `{$drop.files}`.
/// `optimistic` shows a drop at once, before its action's `run` is done: the rows carried move
/// to where they were let go, and files brought in show as rows there (marked `$pending`, from
/// `placeholder`), until the list's own rows change (the app's answer) or the run ends.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct DropSpec {
    pub on: Action,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub files: Option<Action>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub optimistic: bool,
    /// The row each file brought in shows as while it's pending: its templates read
    /// `{$file.path}` and `{$file.name}`. Without one, a row of `path` and `name`. Its key is
    /// `pending:` and the path.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub placeholder: Option<Value>,
}

/// A node: what it is (`type` and its fields) plus the parts every node shares.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Node {
    /// Stable identity. A node with an id keeps its selection and scroll across pushes, can be
    /// focused (lists, tables) and can be replaced alone (`patch`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    /// Its share of the parent row/col: `12` (cells), `"48px"`, `"30%"`, `"*"` (the default),
    /// `"2*"`, or `"fit"` (as big as what it shows).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub size: Option<Size>,
    /// A title draws a border with it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub border: bool,
    /// The border: `rounded` (default), `double`, `thick` or `plain`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub edge: Option<String>,
    /// `left` (default), `center` or `right`, for text and big numbers.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub align: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub style: Option<Style>,
    /// A callout that follows the mouse over this node's rows, filled from the hovered row.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tip: Option<Tip>,
    /// What a click does (after focusing the node and selecting the clicked row).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub click: Option<Action>,
    /// A list, tree or table whose rows can be picked several at a time: ⌘-click (⌥-click in a
    /// terminal) picks one in or out, ⇧-click and ⇧↑/↓ a range, ⌘A all of them.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub multi: bool,
    /// A list, tree or table whose rows can be dragged to a new place among its own rows: a press
    /// that moves lifts the row (or every picked row), and letting go over a row runs `on`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub drop: Option<DropSpec>,
    /// A pixel panel behind the node (rounded, shadowed), where the terminal draws images; a plain
    /// border where it doesn't.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub backdrop: Option<Backdrop>,
    /// Text drawn this many times larger (kitty's text sizing, OSC 66), where the terminal can.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub scale: Option<u8>,
    /// The data source this node reads (a key of `Ui::data`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bind: Option<String>,
    /// Keys that work while this node has focus.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub keys: BTreeMap<String, Action>,
    /// A named look from the active theme's `variants` (its style, border and backdrop).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub variant: Option<String>,
    /// A meaning for the text colour, as a theme token: `warn`, `neg`, `accent`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tone: Option<String>,
    /// Space inside the node's border, over its style's: one length for every side, `[x, y]`, or
    /// `[top, right, bottom, left]`. A length is cells (`1`), pixels (`"8px"`) or a `space` name.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pad: Option<Lens>,
    /// Space outside it, between it and what's beside it: lengths as `pad`'s.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub margin: Option<Lens>,
    /// Shown only while this holds: a bind that's set (`"dialog"`; not empty, false, 0 or null),
    /// not set (`"!dialog"`), or compared with a value (`"mode=edit"`, `"$screen.width>=120"`;
    /// `=`, `!=`, `<`, `<=`, `>`, `>=`); several joined by ` & ` must all hold. A hidden node
    /// takes no room and no focus.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub when: Option<String>,
    /// While this holds (a condition, as `when` is), the node is in its `on` state: a toggle
    /// (`"on": "playing"`, `"on": "loved/{id}"`) styled by the theme's `button.on` or its
    /// variant's, one node for both looks.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub on: Option<String>,
    /// In a `stack`: where the node floats over the ones before it, instead of filling it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub float: Option<Float>,
    /// While shown, focus stays inside this node and what's behind it dims: a dialog.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub modal: bool,
    /// Bounds on the node's share of its row or column, as lengths: `"size": "60%", "max": "720px"`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub min: Option<Len>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max: Option<Len>,
    /// Where it sits across its row or column, over the container's `items`.
    #[serde(rename = "self", default, skip_serializing_if = "Option::is_none")]
    pub align_self: Option<Filled<Align>>,
    /// Width over height, a number (`1.5`) or `"16/9"`. With no `size`, its length along its
    /// row or column comes from how big it is across.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub aspect: Option<Aspect>,
    /// In a `grid`, how many of its columns it takes (default one).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub span: Option<u16>,
    /// A `col`, `grid` or `each` scrolls down, a `row` across, when what it holds is longer than
    /// it is (the wheel, Page Up and Down, the focus brought into view); the offset is kept by id.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub scroll: bool,
    /// A drag handle on its bottom edge (the window): dragging it sets how tall the node is, kept
    /// in the store under this key (a template; pixels, a number) when the drag lets go, so it
    /// holds across rows and sessions. Down a column, a height kept there stands for `size`,
    /// within `min` and `max` and never under a line; with none, `size` holds.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resize: Option<String>,
    #[serde(flatten)]
    pub kind: Kind,
}

/// Where a floating node sits in its stack: `width` and `height` (cells, `"50%"`, `"240px"`; default the
/// whole stack) and `at` (`center`, the default, or `top`, `bottom`, `left`, `right` and the
/// corners, `top-right`), `margin` in from the edges (lengths as a node's `pad`). `x` and `y`
/// (lengths) put its left or top edge that far in from the stack's instead, as data may: an
/// event on a calendar's day.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Float {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub x: Option<Len>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub y: Option<Len>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<Size>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub height: Option<Size>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub at: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub margin: Option<Lens>,
}

impl Default for Node {
    fn default() -> Self {
        Node {
            id: None,
            size: None,
            title: None,
            border: false,
            style: None,
            bind: None,
            keys: BTreeMap::new(),
            edge: None,
            align: None,
            tip: None,
            click: None,
            multi: false,
            drop: None,
            backdrop: None,
            scale: None,
            variant: None,
            tone: None,
            pad: None,
            margin: None,
            when: None,
            on: None,
            float: None,
            modal: false,
            min: None,
            max: None,
            align_self: None,
            aspect: None,
            span: None,
            scroll: false,
            resize: None,
            kind: Kind::Text { text: String::new(), wrap: None, lines: None },
        }
    }
}

/// The closed set of components. Layouts arrange these; they don't add new ones.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "lowercase")]
pub enum Kind {
    /// Children stacked top to bottom, `gap` apart (a length, or `[x, y]`). With `wrap`, those
    /// that don't fit go on in a column beside.
    Col {
        children: Vec<Node>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        gap: Option<Gap>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        justify: Option<Filled<Justify>>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        items: Option<Filled<Align>>,
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        wrap: bool,
    },
    /// Children side by side, `gap` apart (a length, or `[x, y]`). With `wrap`, those that don't
    /// fit go on to the next line, each line as tall as its tallest.
    Row {
        children: Vec<Node>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        gap: Option<Gap>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        justify: Option<Filled<Justify>>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        items: Option<Filled<Align>>,
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        wrap: bool,
    },
    /// Children in columns, a line at a time: `cols` is a count, as many as fit at least
    /// `{"min": len}` wide, or a size per column (`["200px", "*", "2*"]`); a child takes `span`
    /// columns. Lines are as tall as their tallest child, `gap` apart (a length, or `[x, y]`),
    /// and the columns line up from line to line.
    Grid {
        children: Vec<Node>,
        cols: Cols,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        gap: Option<Gap>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        items: Option<Filled<Align>>,
    },
    /// Children over each other, the last on top: each fills the stack, or floats where its
    /// `float` says (a dialog, a popup, a corner badge). With `when`, a layer comes and goes.
    Stack { children: Vec<Node> },
    /// A labelled control: Enter or Space while focused, or a click, runs its `click`.
    Button { label: String },
    /// The `template` node once for each item of the bound array, top to bottom (side by side
    /// with `row`), `gap` apart. In the template, `{$item}` and `{$item.path}` are filled from the
    /// item (ids, binds, `doc`, `size`: `"id": "panel-{$item.id}"`); every other placeholder is
    /// left for the node itself, but `{$index}` and `{$count}` (where it is, from 0, of how many).
    /// An instance's share is its `size`, else an equal one. `wrap` is a row's or column's; with
    /// `cols` the instances are a `grid`'s children instead, and with `stack` a stack's, each
    /// floating where its `float` says (`"y": "{$item.start}"`).
    Each {
        template: Box<Node>,
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        row: bool,
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        stack: bool,
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        wrap: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        cols: Option<Cols>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        gap: Option<Gap>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        justify: Option<Filled<Justify>>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        items: Option<Filled<Align>>,
    },
    /// Where toasts show, newest first, a line each, instead of the screen's corner (a bar of
    /// the UI's own). Each takes the theme part `toast.<tone>`, else `toast`.
    Toasts {},
    /// A turning glyph before `text` (a template): something is under way. A bound source that
    /// hasn't arrived shows one too.
    Spinner {
        #[serde(default, skip_serializing_if = "String::is_empty")]
        text: String,
    },
    /// Text. `{field}` placeholders fill from the bound value (`{a.b}` reaches in). A line with
    /// no tab or fill wraps; `wrap: false` keeps each line on one, cut with `…` where it doesn't
    /// fit, and `lines` shows at most that many, the last ending in `…`.
    Text {
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        wrap: Option<bool>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        lines: Option<u16>,
    },
    /// A selectable list of `items`, or of the bound array, drawn as `Rows` say.
    List {
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        items: Vec<Value>,
        #[serde(flatten)]
        rows: Rows,
    },
    /// An outline over the bound array (or `items`): each row's `nest` (default `children`) holds
    /// the rows under it. Rows fold and unfold (←/→, space); `open: false` starts them folded.
    /// Rows are drawn as `Rows` say, after their indent and a fold glyph (`▾`, `▸`, or `leaf`
    /// for a row with nothing under it, default `· `), and templates can read `{$depth}`,
    /// `{$kids}` (how many rows are under it) and `{$open}`. Store actions on the selected row
    /// reach it where it sits (`$ptr`, a JSON Pointer into the bound entry).
    Tree {
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        items: Vec<Value>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        nest: Option<String>,
        #[serde(default = "yes", skip_serializing_if = "Clone::clone")]
        open: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        leaf: Option<String>,
        #[serde(flatten)]
        rows: Rows,
    },
    /// A line filling the node: `glyph` (default `│` when taller than wide, else `─`).
    Rule {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        glyph: Option<String>,
    },
    /// A selectable table over the bound array (or `items`).
    Table {
        columns: Vec<Column>,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        items: Vec<Value>,
        /// As a list's `filter`.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        filter: Option<String>,
    },
    /// A sparkline over numbers: `values`, or `field` of each bound item.
    Sparkline {
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        values: Vec<f64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        field: Option<String>,
    },
    /// Lines over shared axes. Each series reads numbers from a bind (and `field` of each item).
    Chart {
        series: Vec<Series>,
        /// Labels spread along the x axis.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        labels: Vec<String>,
    },
    /// Bars over the bound array (or `items`): `label` is a template, `value` a path. Negative
    /// values hang below a zero line.
    Bars {
        label: String,
        value: String,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        items: Vec<Value>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        width: Option<u16>,
        /// One row per item, the bar growing to the right, the label before it and the value
        /// after it, instead of columns.
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        horizontal: bool,
    },
    /// A filled bar: `value` (a template giving a number) out of `of` (a number or a template,
    /// default 1). Not `max`, which is every node's own: how big it can grow.
    Gauge {
        value: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        of: Option<Value>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        label: Option<String>,
    },
    /// Large digits (a KPI): the filled template, in a 3-row block font.
    Big { text: String },
    /// A multi-line text editor (caretline) on a text entry in the store: `bind` names the
    /// entry (default: the editor's id), and `text` seeds it when it doesn't exist yet. With
    /// `doc`, the entry's name is a template over the bound value instead: `"bind": "@notes",
    /// "doc": "note/{id}"` edits the selected note, and `text` (`"{body}"`) fills from it too.
    /// The text and its undo history are the store's, so a push that drops the editor loses
    /// nothing; the carets and scroll are the editor's, one set per entry it has shown. While it
    /// has focus it takes every key except Tab, Shift-Tab and Esc, so Ctrl-C copies there.
    Editor {
        #[serde(default, skip_serializing_if = "String::is_empty")]
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        doc: Option<String>,
        /// Shown, dimmed, while the text is empty.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        placeholder: Option<String>,
        /// `markdown` styles headings, list markers, quotes and inline code (theme parts
        /// `md.heading`, `md.bullet`, `md.quote`, `md.code`), and task items (`- [ ]`, `- [x]`:
        /// `md.task`, `md.done`): Ctrl-T makes the lines it's on tasks and ticks them (see `tasks`), a click
        /// on a box ticks it. The text stays plain.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        syntax: Option<String>,
        /// Shows the text without changing it: the carets move, select and copy, the wheel and
        /// the keys scroll. A long text or a log to read.
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        readonly: bool,
        /// `indent`: the editor keeps Tab and Shift-Tab, which indent and outdent the lines of the
        /// selection (or a list item; else Tab types two spaces). `indent-lines`: Tab always
        /// indents the lines the caret or the selection is on, as an outliner does. Esc leaves.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        tab: Option<String>,
        /// What Ctrl-T does to a ticked task in a Markdown editor: `toggle` (the default) unticks
        /// it; `cycle` makes it plain text again, so text → task → done → text.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        tasks: Option<String>,
        /// Where the caret starts the first time the editor shows an entry: `start` (the
        /// default) or `end`. Shown again, an entry keeps its caret.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        caret: Option<String>,
        /// Spans of the text that act on a click: `wiki` (`[[Page]]`), `tag` (`#tag`) or `url`,
        /// each with a `click` and an `s-click` (Shift) action, whose templates read `{$match}`
        /// (the page, the tag, the address). A key reads the link at the caret as `{$link}`.
        /// Links take the theme part `md.link`.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        links: Vec<LinkSpec>,
        /// Ordered lists kept in number, with a marker style per depth for a new level:
        /// `["1.", "a.", "i."]`. After every edit, each list's items are renumbered in its own
        /// style (numbers, letters, roman); Tab and Shift-Tab move an item to the next depth's
        /// style. A `{"list_style": "next"}` key changes one list's style.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        ordered: Vec<String>,
    },
    /// A one-line field (caretline, single-line): an editor whose text never holds a line
    /// break. Enter runs the node's `keys.enter`, so a form submits with a store action.
    Input {
        #[serde(default, skip_serializing_if = "String::is_empty")]
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        placeholder: Option<String>,
        /// `number`: typing that can't make a number is refused, and the node's keys (Enter)
        /// don't run until the text is one.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        accept: Option<String>,
        /// The node's keys (Enter) don't run while the text is blank: a name a form needs.
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        required: bool,
    },
    /// One child at a time, picked by a row of tab titles (click one, or ←/→ when focused). The
    /// titles are templates over the node's bound value (`"Inbox {inbox}"`), and the row can
    /// start with `lead` and end with `trail` (templates too: a name, a date).
    Tabs {
        tabs: Vec<String>,
        /// A page per tab, in order; a tab without one shows nothing, so tabs with no children
        /// are a bar of choices (a segmented control, a radio group).
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        children: Vec<Node>,
        /// The tab shown first (default 0), until the person or an action picks another.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        tab: Option<usize>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        lead: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        trail: Option<String>,
    },
    /// Lines drawn in pixels (anti-aliased, a gradient under each) where the terminal draws
    /// images; a braille chart where it doesn't.
    Plot {
        series: Vec<Series>,
        #[serde(default = "yes")]
        fill: bool,
        /// Line width as a fraction of a cell's height.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        width: Option<f32>,
    },
    /// An image file, scaled into the node keeping its proportions. `src` is a template over the
    /// bound value (`"{preview}"` bound to `@files` follows a selection). The window draws PNG,
    /// JPEG, GIF, WebP, BMP and TIFF; a terminal PNG only. `fit: "cover"` fills the node,
    /// cropping; `alt` shows where it can't be drawn.
    Image {
        src: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        fit: Option<Fit>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        alt: Option<String>,
    },
    /// Vector art: inline SVG markup (`{field}` placeholders filled from the bound value, so it
    /// can draw live data) or an `.svg` file, rendered at the terminal's real pixel size. `alt`
    /// shows where the terminal has no graphics.
    Svg {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        svg: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        src: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        alt: Option<String>,
    },
    /// A lit, glowing dot (the brand mark's `•`): `color`, and `glow` (0 for none).
    Dot {
        color: String,
        #[serde(default)]
        glow: f32,
    },
    /// A world map with a point per bound item at `lat`/`lon` (paths), labelled by `label`.
    Map {
        lat: String,
        lon: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        label: Option<String>,
    },
}

fn yes() -> bool {
    true
}

/// How a list or a tree draws its rows, and which row is which.
///
/// - `item` formats a row (a template over it); with `row_variant` (a path), a row whose value
///   there is a key of `variants` uses that template instead (a section header, a blank), and
///   rows whose variant is in `skip` can't be selected. (`variant`, as on every node, is the
///   node's look from the theme.)
/// - `mark` and `lead` start the selected and the other rows (a list's default `▸ ` and two
///   spaces; a tree's none); `selected` styles the selected row (a style spec; default reverse
///   while focused).
/// - `lines`: every row takes this many lines (the template's lines), the selection all of them.
/// - `keep`: the left side of a row keeps at least this many cells before its right side (after
///   a tab) is cut.
/// - `key` (default `id`): the path that names a row, so the selection stays on it when rows
///   come and go, and a tree's folds stay with it.
/// - `filter`: show only the rows matching the text in this store entry (or bind): every word
///   of it, in any case, somewhere in the row's values.
/// - `empty`: what shows when there are no rows.
/// - `row`: a node drawn for each row instead of `item`, its `{$item}` and `{$item.path}`
///   filled from the row as an `each` template's are: a picture, a name, a badge. It's as tall
///   as its `size` in cells (else `lines`). A press anywhere in it is a press on the row, so
///   its nodes take no clicks or focus of their own.
/// - `cols`: rows to a line, a grid of them; ↑/↓ move a line, ←/→ a row. A number, or
///   `{"min": "180px"}` for as many as fit with each at least that wide (`state::per_line`).
/// - `section`: a heading across the whole width wherever the rows' `by` value changes, drawn
///   from its `row` template filled from the first row of the group (`{$item.name}`, and
///   `{$item.$rows}` for how many rows it has). Headings take no selection, keys or picks: they
///   only start a new line (`state::Lines`).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Rows {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub row: Option<Box<Node>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cols: Option<Cols>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub item: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub empty: Option<String>,
    #[serde(default, rename = "row_variant", skip_serializing_if = "Option::is_none")]
    pub variant: Option<String>,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub variants: BTreeMap<String, String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub skip: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mark: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lead: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub selected: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lines: Option<u16>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub keep: Option<u16>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub key: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub filter: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub section: Option<Section>,
}

/// A list's group headings (`Rows::section`): the path whose value groups the rows, and the node
/// drawn as each group's heading.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Section {
    pub by: String,
    pub row: Box<Node>,
}

impl Section {
    /// The group row `r` is in: its value at `by`, as text (empty: in no group).
    pub fn of(&self, r: &Value) -> String {
        scalar(lookup(r, &self.by))
    }

    /// What a group's heading is filled from: its first row (but a placeholder a drop put there
    /// before the app answered), with `$rows` how many it has.
    pub fn item(&self, group: &[Value]) -> Value {
        let first = group.iter().find(|r| r.get("$pending") != Some(&Value::Bool(true))).or(group.first());
        let mut v = first.cloned().unwrap_or(Value::Null);
        if let Value::Object(m) = &mut v {
            m.insert("$rows".into(), group.len().into());
        }
        v
    }

    /// Its heading's height in cells when its template says (`size` in cells), else none: measured.
    pub fn height(&self) -> Option<f32> {
        match self.row.size.as_ref().map(Size::measure) {
            Some(Measure::Cells(c)) => Some(c.max(1) as f32),
            _ => None,
        }
    }
}

/// A pixel panel: `fill` (and `fill2` for a vertical gradient), `border`, a corner `radius` and a
/// `shadow` (fractions of a cell's height), and `glow` (the shadow's colour, for a lit panel).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Backdrop {
    pub fill: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fill2: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub border: Option<String>,
    #[serde(default = "radius")]
    pub radius: f32,
    #[serde(default)]
    pub shadow: f32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub glow: Option<String>,
}

fn radius() -> f32 {
    0.5
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Series {
    pub name: String,
    pub bind: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub field: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Tip {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    pub text: String,
}

/// A cell's background from its value: `min` is the `neg` colour, `max` the `pos` colour.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Heat {
    pub value: String,
    pub min: f64,
    pub max: f64,
}

impl Heat {
    /// Where a row's `value` (a template, `"{chg}"`) sits from `min` (0) to `max` (1), held to
    /// them; None when it doesn't read as a number. A window colours it from the theme's `neg`
    /// through the panel at the middle to `pos`.
    pub fn at(&self, row: &Value) -> Option<f32> {
        let v = number(&fill_raw(&self.value, row))?;
        let span = self.max - self.min;
        Some(if span.abs() < 1e-9 { 0.5 } else { ((v - self.min) / span).clamp(0., 1.) as f32 })
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Column {
    pub title: String,
    /// A template over the row, e.g. `"{text}"` or `"{due} {priority}"`.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub value: String,
    /// The column's cells as a node template instead of `value`'s text, filled from `$item` as a
    /// list's `row` (a chip, a badge, a button with its own click).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cell: Option<Box<Node>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub size: Option<Size>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub align: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub heat: Option<Heat>,
    /// Sum this path of every row in a footer under the column (numbers, or strings that read as
    /// numbers).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub total: Option<String>,
}

impl Column {
    /// Its `total` over these rows, and as it's written: thousands grouped, cents when there are
    /// any (`12,480.50`).
    pub fn total(&self, rows: &[Value]) -> Option<(f64, String)> {
        let path = self.total.as_deref()?;
        let sum: f64 = rows.iter().filter_map(|r| lookup(r, path)).filter_map(|v| v.as_f64().or_else(|| v.as_str().and_then(number))).sum();
        Some((sum, grouped(sum)))
    }
}

/// A table's footer, a cell a column: its total, or `Total` under the first column when that
/// has none, else nothing.
pub fn table_footer(columns: &[Column], rows: &[Value]) -> Vec<String> {
    columns.iter().enumerate().map(|(k, c)| c.total(rows).map(|(_, t)| t).unwrap_or_else(|| if k == 0 { "Total".into() } else { String::new() })).collect()
}

/// A number with its thousands grouped and cents when it has any: `12,480`, `-3.50`.
pub fn grouped(x: f64) -> String {
    let neg = x < 0.0;
    let cents = (x.abs() * 100.0).round() as u64;
    let (whole, frac) = (cents / 100, cents % 100);
    let digits = whole.to_string();
    let mut out = String::new();
    for (i, ch) in digits.chars().enumerate() {
        if i > 0 && (digits.len() - i) % 3 == 0 {
            out.push(',');
        }
        out.push(ch);
    }
    let sign = if neg && cents > 0 { "-" } else { "" };
    if frac == 0 { format!("{sign}{out}") } else { format!("{sign}{out}.{frac:02}") }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Size {
    Cells(u16),
    Spec(String),
}

/// A size, read: what a `Size` asks of its row or column.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Measure {
    /// `12` or `"12"`: that many columns or rows.
    Cells(u16),
    /// `"48px"`: exact in a window; a terminal rounds it to its cells.
    Px(f32),
    /// `"30%"` of the parent.
    Percent(f32),
    /// `"*"`, `"2*"`: a share of what's left (anything unreadable is one share).
    Share(u16),
    /// `"fit"`: as big as what it shows, given way when there isn't room.
    Fit,
}

impl Size {
    pub fn measure(&self) -> Measure {
        let s = match self {
            Size::Cells(n) => return Measure::Cells(*n),
            Size::Spec(s) => s.trim(),
        };
        if s == "fit" {
            return Measure::Fit;
        }
        if let Some(p) = s.strip_suffix('%') {
            return p.trim().parse().map_or(Measure::Share(1), Measure::Percent);
        }
        if let Some(p) = s.strip_suffix("px") {
            return p.trim().parse().map_or(Measure::Share(1), Measure::Px);
        }
        if let Some(w) = s.strip_suffix('*') {
            return Measure::Share(if w.is_empty() { 1 } else { w.trim().parse().unwrap_or(1) });
        }
        s.parse().map_or(Measure::Share(1), Measure::Cells)
    }
}

/// A whole style: a node's own `style`, a variant's, and a theme part written as an object.
/// Colours are tokens or colours; `pad`, `radius`, `shadow` and `type` may name the theme's
/// scales. A style never arranges: no size, gap or position.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Style {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fg: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bg: Option<Fill>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub bold: bool,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub dim: bool,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub italic: bool,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub underline: bool,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub strike: bool,
    /// Foreground and background swapped.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub reverse: bool,
    /// A type role from the theme's `type`.
    #[serde(default, rename = "type", skip_serializing_if = "Option::is_none")]
    pub role: Option<String>,
    /// Space inside: one length for every side, `[x, y]`, or `[top, right, bottom, left]`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pad: Option<Lens>,
    /// Corner radius: pixels, or a `radius` name.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub radius: Option<Len>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub border: Option<Line>,
    /// A `depth` name (`e2`), or `none`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub shadow: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ring: Option<Ring>,
    /// A shape the component takes: tabs `underline`, `pill`, `segment`, `plain`; a scrollbar
    /// `thin`, `overlay`, `none`; an edge `rounded`, `square`, `double`, `thick`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub shape: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub opacity: Option<f32>,
    /// `default`, `pointer`, `text` or `grab`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cursor: Option<String>,
    /// Fields no style has, kept so they can be reported as problems instead of ignored.
    #[serde(flatten, default, skip_serializing_if = "BTreeMap::is_empty")]
    pub other: BTreeMap<String, Value>,
}

/// A length for each side of a box, as CSS: one for every side, `[x, y]` (left and right, top
/// and bottom), or `[top, right, bottom, left]`.
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum Lens {
    One(Len),
    XY([Len; 2]),
    Sides([Len; 4]),
}

impl Lens {
    /// Top, right, bottom and left.
    pub fn sides(&self) -> [&Len; 4] {
        match self {
            Lens::One(l) => [l; 4],
            Lens::XY([x, y]) => [y, x, y, x],
            Lens::Sides([t, r, b, l]) => [t, r, b, l],
        }
    }

    /// The lengths as written.
    pub fn written(&self) -> &[Len] {
        match self {
            Lens::One(l) => std::slice::from_ref(l),
            Lens::XY(a) => a,
            Lens::Sides(a) => a,
        }
    }
}

/// Space between a container's children: one length, or `[x, y]` (across and down).
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum Gap {
    One(Len),
    XY([Len; 2]),
}

impl Gap {
    /// Across and down.
    pub fn xy(&self) -> [&Len; 2] {
        match self {
            Gap::One(l) => [l; 2],
            Gap::XY([x, y]) => [x, y],
        }
    }

    /// The lengths as written.
    pub fn written(&self) -> &[Len] {
        match self {
            Gap::One(l) => std::slice::from_ref(l),
            Gap::XY(a) => a,
        }
    }
}

/// Where a node sits across its row or column (`self`), or where a container puts its children
/// across (`items`): `start`, `center`, `end`, `stretch` (the default) or `baseline`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Align {
    Start,
    Center,
    End,
    Stretch,
    Baseline,
}

/// Where a container puts its children along it, in the room they leave: `start` (the default),
/// `center`, `end`, `between` (the room between them) or `around` (around each).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Justify {
    Start,
    Center,
    End,
    Between,
    Around,
}

/// A field a template may fill from data: its value, or a placeholder kept as written
/// (`"justify": "{$item.side|me=end;*=start}"`) until an `each` or a list's row fills it, when
/// it's read again as the value. Unfilled it counts as unset, and is a problem.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Filled<T> {
    Is(T),
    Hole(String),
}

impl<T: Copy> Filled<T> {
    /// The value, if it's been filled.
    pub fn get(&self) -> Option<T> {
        match self {
            Filled::Is(t) => Some(*t),
            Filled::Hole(_) => None,
        }
    }
}

impl<T: Serialize> Serialize for Filled<T> {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        match self {
            Filled::Is(t) => t.serialize(s),
            Filled::Hole(h) => s.serialize_str(h),
        }
    }
}

impl<'de, T: serde::de::DeserializeOwned> Deserialize<'de> for Filled<T> {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        match Value::deserialize(d)? {
            Value::String(h) if h.contains('{') => Ok(Filled::Hole(h)),
            v => serde_json::from_value(v).map(Filled::Is).map_err(serde::de::Error::custom),
        }
    }
}

/// How many to a line, and how wide each is: a number of equal columns, as many equal ones as
/// fit at least `min` wide (a length; how many depends on the width a frame lays them out
/// across), up to `max` if it says, or a size per column (`["200px", "*", "2*"]`, as a node's
/// `size`).
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum Cols {
    Count(u16),
    Fill {
        min: Len,
        #[serde(skip_serializing_if = "Option::is_none")]
        max: Option<u16>,
    },
    Tracks(Vec<Size>),
}

impl Cols {
    /// How many to a line across `width` pixels, a length resolving to pixels by `px`.
    pub fn count(&self, width: f32, px: impl Fn(&Len) -> Option<f32>) -> usize {
        match self {
            Cols::Count(n) => (*n).max(1) as usize,
            Cols::Fill { min, max } => match px(min) {
                Some(m) if m > 0. => ((width / m).floor() as usize).min(max.map_or(usize::MAX, |x| x.max(1) as usize)).max(1),
                _ => 1,
            },
            Cols::Tracks(t) => t.len().max(1),
        }
    }

    /// Each column's size, `count` of them: its own, or an equal share.
    pub fn tracks(&self, count: usize) -> Vec<Measure> {
        match self {
            Cols::Tracks(t) if !t.is_empty() => t.iter().map(Size::measure).collect(),
            _ => vec![Measure::Share(1); count.max(1)],
        }
    }
}

/// Lines of a grid of `cols` columns, each child taking `spans[k]` of them (at least one, at
/// most all): each line its children as (child, first column, columns), a child that doesn't
/// fit on the line going to the next.
pub fn grid_lines(spans: &[usize], cols: usize) -> Vec<Vec<(usize, usize, usize)>> {
    let cols = cols.max(1);
    let mut lines: Vec<Vec<(usize, usize, usize)>> = Vec::new();
    let mut at = cols;
    for (k, span) in spans.iter().map(|s| (*s).clamp(1, cols)).enumerate() {
        if at + span > cols {
            lines.push(Vec::new());
            at = 0;
        }
        lines.last_mut().expect("a line").push((k, at, span));
        at += span;
    }
    lines
}

/// Width over height: a number (`1.5`), or `"16/9"`, kept as written.
#[derive(Clone, Debug, PartialEq)]
pub enum Aspect {
    Number(f32),
    Ratio(String),
}

// A whole number as an integer, as `Len`'s cells.
impl Serialize for Aspect {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        match self {
            Aspect::Number(n) => Len::Cells(*n).serialize(s),
            Aspect::Ratio(r) => s.serialize_str(r),
        }
    }
}

impl Aspect {
    pub fn ratio(&self) -> f32 {
        match self {
            Aspect::Number(n) => *n,
            Aspect::Ratio(s) => ratio_of(s).unwrap_or(1.),
        }
    }
}

/// `"16/9"` as 16 over 9, both more than nothing.
fn ratio_of(s: &str) -> Option<f32> {
    let (w, h) = s.split_once('/')?;
    let (w, h) = (w.trim().parse::<f32>().ok()?, h.trim().parse::<f32>().ok()?);
    (w > 0. && h > 0. && (w / h).is_finite()).then_some(w / h)
}

impl Len {
    /// In pixels, a cell being `per` of them: cells, `"8px"`, or a number as text. A `space`
    /// name isn't one until the theme fills it in (`style::Theme::len`).
    pub fn px(&self, per: f32) -> Option<f32> {
        match self {
            Len::Cells(n) => Some(n * per),
            Len::Spec(s) => match s.trim().strip_suffix("px") {
                Some(p) => p.trim().parse().ok(),
                None => s.trim().parse::<f32>().ok().map(|n| n * per),
            },
        }
    }
}

// The untagged enums above, read by hand, so a wrong value says what was expected instead of
// "did not match any variant".

fn wrong<E: serde::de::Error>(what: &str, v: &Value) -> E {
    E::custom(format!("{what}, not {v}"))
}

impl<'de> Deserialize<'de> for Part {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        match Value::deserialize(d)? {
            Value::String(s) => Ok(Part::Ink(s)),
            v @ Value::Object(_) => serde_json::from_value(v).map(|s| Part::Whole(Box::new(s))).map_err(serde::de::Error::custom),
            v => Err(wrong("a part is a spec (\"accent+b\") or a style object", &v)),
        }
    }
}

fn len_of<E: serde::de::Error>(v: Value) -> Result<Len, E> {
    match v {
        Value::Number(n) => Ok(Len::Cells(n.as_f64().unwrap_or_default() as f32)),
        Value::String(s) => Ok(Len::Spec(s)),
        v => Err(wrong("a length is cells (1), pixels (\"8px\") or a name (\"s2\")", &v)),
    }
}

impl<'de> Deserialize<'de> for Len {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        len_of(Value::deserialize(d)?)
    }
}

fn lens_of<E: serde::de::Error, const N: usize>(a: Vec<Value>) -> Result<[Len; N], E> {
    let v: Vec<Len> = a.into_iter().map(len_of).collect::<Result<_, E>>()?;
    v.try_into().map_err(|_| E::custom("wrong count"))
}

impl<'de> Deserialize<'de> for Lens {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        match Value::deserialize(d)? {
            Value::Array(a) if a.len() == 2 => lens_of(a).map(Lens::XY),
            Value::Array(a) if a.len() == 4 => lens_of(a).map(Lens::Sides),
            v @ Value::Array(_) => Err(wrong("sides are one length, [x, y] or [top, right, bottom, left]", &v)),
            v => len_of(v).map(Lens::One),
        }
    }
}

impl<'de> Deserialize<'de> for Gap {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        match Value::deserialize(d)? {
            Value::Array(a) if a.len() == 2 => lens_of(a).map(Gap::XY),
            v @ Value::Array(_) => Err(wrong("a gap is one length or [x, y]", &v)),
            v => len_of(v).map(Gap::One),
        }
    }
}

impl<'de> Deserialize<'de> for Cols {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        match Value::deserialize(d)? {
            Value::Number(n) if n.as_u64().is_some_and(|n| (1..=u16::MAX as u64).contains(&n)) => Ok(Cols::Count(n.as_u64().unwrap_or(1) as u16)),
            Value::Object(mut o) if o.contains_key("min") && o.keys().all(|k| k == "min" || k == "max") && o.get("max").is_none_or(|m| m.as_u64().is_some_and(|m| m >= 1)) => {
                let max = o.remove("max").and_then(|m| m.as_u64()).map(|m| m.min(u16::MAX as u64) as u16);
                len_of(o.remove("min").unwrap_or_default()).map(|min| Cols::Fill { min, max })
            }
            Value::Array(a) if !a.is_empty() && a.iter().all(|t| t.is_string() || t.is_u64()) => serde_json::from_value(Value::Array(a)).map(Cols::Tracks).map_err(serde::de::Error::custom),
            v => Err(wrong("cols is a count (3), as many as fit at least a length wide, up to a most ({\"min\": \"180px\", \"max\": 4}), or a size per column ([\"200px\", \"*\", \"2*\"])", &v)),
        }
    }
}

impl<'de> Deserialize<'de> for Aspect {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        match Value::deserialize(d)? {
            Value::Number(n) if n.as_f64().is_some_and(|n| n > 0.) => Ok(Aspect::Number(n.as_f64().unwrap_or(1.) as f32)),
            Value::String(s) if ratio_of(&s).is_some() => Ok(Aspect::Ratio(s)),
            v => Err(wrong("an aspect is width over height, a number (1.5) or \"16/9\"", &v)),
        }
    }
}

impl<'de> Deserialize<'de> for Line {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        struct Whole {
            #[serde(default)]
            width: Option<f32>,
            #[serde(default)]
            color: Option<String>,
            #[serde(default)]
            style: Option<String>,
        }
        match Value::deserialize(d)? {
            Value::String(s) => {
                let mut line = Line::default();
                for w in s.split_whitespace() {
                    let px = w.strip_suffix("px").unwrap_or(w).parse::<f32>().ok();
                    match (px, w) {
                        (Some(n), _) if line.width.is_none() => line.width = Some(n),
                        (_, "solid" | "dashed" | "double") if line.style.is_none() => line.style = Some(w.to_string()),
                        _ if line.color.is_none() => line.color = Some(w.to_string()),
                        _ => return Err(serde::de::Error::custom(format!("a border is \"[width] [solid|dashed|double] [colour]\", not {s:?}"))),
                    }
                }
                Ok(line)
            }
            v @ Value::Object(_) => serde_json::from_value::<Whole>(v).map(|w| Line { width: w.width, color: w.color, style: w.style }).map_err(serde::de::Error::custom),
            v => Err(wrong("a border is {\"width\", \"color\", \"style\"} or \"2px dashed accent\"", &v)),
        }
    }
}

impl<'de> Deserialize<'de> for Fill {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let v = Value::deserialize(d)?;
        let text = |k: &str| v.get(k).and_then(Value::as_str).map(str::to_string);
        match &v {
            Value::String(s) => Ok(Fill::Colour(s.clone())),
            Value::Object(_) => match (text("from"), text("to")) {
                (Some(from), Some(to)) => Ok(Fill::Gradient { from, to, angle: v.get("angle").and_then(Value::as_f64).map_or(down(), |a| a as f32) }),
                _ => Err(wrong("a gradient is {\"from\", \"to\", \"angle\"}", &v)),
            },
            _ => Err(wrong("a background is a colour or a gradient {\"from\", \"to\", \"angle\"}", &v)),
        }
    }
}

impl Style {
    /// The style's ink as a spec (`fg+on-panel+b`): its colours (a gradient's first) and
    /// modifiers.
    pub fn spec(&self) -> String {
        let mut words: Vec<String> = self.fg.iter().cloned().collect();
        words.extend(self.bg.as_ref().map(|b| format!("on-{}", b.colour())));
        for (on, m) in [(self.bold, "b"), (self.dim, "d"), (self.italic, "i"), (self.underline, "u"), (self.reverse, "r"), (self.strike, "s")] {
            if on {
                words.push(m.into());
            }
        }
        words.join("+")
    }

    /// This style over `base`: what it says replaces, the rest stays.
    pub fn over(&self, base: &Style) -> Style {
        let mut other = base.other.clone();
        other.extend(self.other.clone());
        Style {
            fg: self.fg.clone().or_else(|| base.fg.clone()),
            bg: self.bg.clone().or_else(|| base.bg.clone()),
            bold: self.bold || base.bold,
            dim: self.dim || base.dim,
            italic: self.italic || base.italic,
            underline: self.underline || base.underline,
            strike: self.strike || base.strike,
            reverse: self.reverse || base.reverse,
            role: self.role.clone().or_else(|| base.role.clone()),
            pad: self.pad.clone().or_else(|| base.pad.clone()),
            radius: self.radius.clone().or_else(|| base.radius.clone()),
            border: match (&self.border, &base.border) {
                (Some(a), Some(b)) => Some(Line {
                    width: a.width.or(b.width),
                    color: a.color.clone().or_else(|| b.color.clone()),
                    style: a.style.clone().or_else(|| b.style.clone()),
                }),
                (a, b) => a.clone().or_else(|| b.clone()),
            },
            shadow: self.shadow.clone().or_else(|| base.shadow.clone()),
            ring: match (&self.ring, &base.ring) {
                (Some(a), Some(b)) => Some(Ring { width: a.width.or(b.width), offset: a.offset.or(b.offset), color: a.color.clone().or_else(|| b.color.clone()) }),
                (a, b) => a.clone().or_else(|| b.clone()),
            },
            shape: self.shape.clone().or_else(|| base.shape.clone()),
            opacity: self.opacity.or(base.opacity),
            cursor: self.cursor.clone().or_else(|| base.cursor.clone()),
            other,
        }
    }
}

/// Where a source's value comes from. A command prints JSON on stdout; `path` picks a part of it
/// (`"items"`); `every` re-runs it (seconds). A `stream` command keeps running and each JSON line
/// it prints replaces the value: a live feed without a process per update. `host` asks the app
/// that embeds the screen (`Host::fetch`, with `args`), in process.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Source {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cmd: Option<Vec<String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub shell: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub stream: Option<Vec<String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub value: Option<Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub path: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub every: Option<f64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub host: Option<String>,
    #[serde(default, skip_serializing_if = "Value::is_null")]
    pub args: Value,
}

/// An editor's or input's settings (see `Kind::Editor`, `Kind::Input`).
#[derive(Clone, Copy, Debug)]
pub struct Field<'a> {
    pub seed: &'a str,
    pub doc: Option<&'a str>,
    pub placeholder: Option<&'a str>,
    /// One line (an input).
    pub line: bool,
    /// Markdown styling.
    pub markdown: bool,
    /// Numbers only (`accept: "number"`).
    pub number: bool,
    /// Its keys wait for some text (`required`).
    pub required: bool,
    /// Read only.
    pub readonly: bool,
    /// Tab and Shift-Tab indent and outdent instead of moving the focus.
    pub indents: bool,
    /// Tab always indents the caret's line (an outliner), never types spaces.
    pub indent_lines: bool,
    /// Ctrl-T on a ticked task makes it plain text again (`tasks: "cycle"`).
    pub task_cycle: bool,
    /// The caret starts at the end of an entry shown for the first time.
    pub caret_end: bool,
    /// Spans that act on a click.
    pub links: &'a [LinkSpec],
    /// Ordered lists kept in number, with these marker styles by depth.
    pub ordered: &'a [String],
}

/// A kind of link in an editor's text and what a click on one does (see `Kind::Editor`).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct LinkSpec {
    pub kind: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub click: Option<Action>,
    #[serde(default, rename = "s-click", skip_serializing_if = "Option::is_none")]
    pub s_click: Option<Action>,
}

/// What a character of a Markdown line is, for whatever draws an editor to style it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Md {
    Text,
    Heading,
    /// A list item's marker (`-`, `12.`).
    Bullet,
    Quote,
    /// Inline `code`, its backticks too.
    Code,
    /// A task's box (`[x]`).
    Task,
    /// The text of a ticked task.
    Done,
    /// A link of one of the editor's kinds (`wiki`, `tag`, `url`).
    Link,
}

/// The role of each character of a Markdown line, in one pass over it (a long paragraph is one
/// line). Later rules win: code, a list marker, a task, a quote or heading line, then links of
/// the kinds given.
pub fn md_roles(line: &str, links: &[&str]) -> Vec<Md> {
    let chars: Vec<char> = line.chars().collect();
    let n = chars.len();
    let mut out = vec![Md::Text; n];
    // Inside a pair of backticks (the backticks too): an odd number before, or an opening one
    // with another after it.
    let mut ticks = 0;
    let last_tick = chars.iter().rposition(|c| *c == '`');
    for (col, c) in chars.iter().enumerate() {
        let here = *c == '`';
        if ticks % 2 == 1 || (here && last_tick.is_some_and(|l| l > col)) {
            out[col] = Md::Code;
        }
        ticks += here as usize;
    }
    let t = line.trim_start();
    let indent = line.chars().count() - t.chars().count();
    let marker = if t.starts_with("- ") || t.starts_with("* ") || t.starts_with("+ ") {
        Some(1)
    } else {
        let digits = t.chars().take_while(char::is_ascii_digit).count();
        (digits > 0 && t[digits..].starts_with(". ")).then_some(digits + 1)
    };
    if let Some(m) = marker {
        for s in out.iter_mut().skip(indent).take(m) {
            *s = Md::Bullet;
        }
    }
    // A task: its box, and the rest of a ticked one done.
    if let Some((b, ticked)) = task_box(line) {
        for (col, s) in out.iter_mut().enumerate() {
            if col + 1 >= b && col <= b + 1 {
                *s = Md::Task;
            } else if ticked && col > b + 1 {
                *s = Md::Done;
            }
        }
    }
    let heading = t.starts_with('#') && !(links.contains(&"tag") && t.chars().nth(1).is_some_and(|c| c.is_alphanumeric()));
    if heading || t.starts_with("> ") || t == ">" {
        out.fill(if heading { Md::Heading } else { Md::Quote });
    }
    if !links.is_empty() {
        for (a, b, ..) in links_in(line, links) {
            for s in out.iter_mut().take(b).skip(a) {
                *s = Md::Link;
            }
        }
    }
    out
}

/// The links in a line, by kind (`wiki`, `tag`, `url`): where each starts and ends (chars) and
/// what it names (the page, the tag without its `#`, the address).
pub fn links_in(line: &str, kinds: &[&str]) -> Vec<(usize, usize, String, String)> {
    let chars: Vec<char> = line.chars().collect();
    let at = |i: usize, pat: &str| pat.chars().enumerate().all(|(k, p)| chars.get(i + k) == Some(&p));
    let (wiki, url, tag) = (kinds.contains(&"wiki"), kinds.contains(&"url"), kinds.contains(&"tag"));
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        if wiki
            && at(i, "[[")
            && let Some(end) = (i + 2..chars.len()).find(|&j| at(j, "]]"))
        {
            let inner: String = chars[i + 2..end].iter().collect();
            if !inner.is_empty() && !inner.contains('\n') {
                out.push((i, end + 2, "wiki".into(), inner));
                i = end + 2;
                continue;
            }
        }
        if url && (at(i, "https://") || at(i, "http://")) {
            let n = chars[i..].iter().take_while(|c| !c.is_whitespace() && !matches!(c, ')' | ']' | '>')).count();
            out.push((i, i + n, "url".into(), chars[i..i + n].iter().collect()));
            i += n;
            continue;
        }
        if tag && chars[i] == '#' && (i == 0 || chars[i - 1].is_whitespace()) {
            let n = chars[i + 1..].iter().take_while(|c| c.is_alphanumeric() || matches!(c, '_' | '-' | '/')).count();
            if n > 0 {
                out.push((i, i + 1 + n, "tag".into(), chars[i + 1..i + 1 + n].iter().collect()));
                i += 1 + n;
                continue;
            }
        }
        i += 1;
    }
    out
}

/// Where a Markdown task item's box is in a line: the column of the char inside `[ ]`, and whether
/// it's ticked. `- [ ] buy milk` gives `(3, false)`; any list marker (`-`, `*`, `+`, `1.`) works.
pub fn task_box(line: &str) -> Option<(usize, bool)> {
    let chars: Vec<char> = line.chars().collect();
    let mut i = chars.iter().take_while(|c| **c == ' ' || **c == '\t').count();
    match chars.get(i)? {
        '-' | '*' | '+' => i += 1,
        c if c.is_ascii_digit() => {
            while chars.get(i).is_some_and(char::is_ascii_digit) {
                i += 1;
            }
            if chars.get(i) != Some(&'.') {
                return None;
            }
            i += 1;
        }
        _ => return None,
    }
    if chars.get(i) != Some(&' ') || chars.get(i + 1) != Some(&'[') || chars.get(i + 3) != Some(&']') {
        return None;
    }
    match chars.get(i + 2)? {
        ' ' => Some((i + 2, false)),
        'x' | 'X' => Some((i + 2, true)),
        _ => None,
    }
}

/// Text that is a number, or the start of one ("", "-", "12.").
pub fn number_so_far(t: &str) -> bool {
    let t = t.strip_prefix('-').unwrap_or(t);
    let mut dot = false;
    t.chars().all(|c| match c {
        '.' if !dot => {
            dot = true;
            true
        }
        c => c.is_ascii_digit(),
    })
}

/// Text that is a whole number: "-12.50", "3", "4.".
pub fn number_done(t: &str) -> bool {
    number_so_far(t) && t.chars().any(|c| c.is_ascii_digit())
}

/// What a key does. Names: `quit`, `up`, `down`, `top`, `bottom`, `focus_next`, `focus_prev`,
/// `refresh`. `run` executes a command (templated against the selected item, `{id}`), then
/// refreshes; `load` replaces the whole UI with a file's; `focus` moves focus to a node;
/// `theme` chooses a theme (`next`, `prev` or a name).
///
/// Store actions write the store, as the person: `append` adds the filled `value` to an array
/// entry, `put` writes one (a string into a text entry replaces its text, undoably), `remove`
/// takes the focused list's selected row out of the array entry it shows, `do` runs several in
/// order (`remove` with `where` takes the rows that match instead). Templates in `value` read `{field}` from the selected row, `{store.key}` from the store
/// and `{$id}`, a fresh id; a string that is one placeholder takes the value with its type.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Action {
    Named(String),
    Run { run: Vec<String> },
    Load { load: String },
    /// Move the focus to a node: an id, a template (`"{store.from}"`), or `$prev`, wherever
    /// it was before it last moved.
    Focus { focus: String },
    /// Select the row of list or tree `in` whose key is `select` (a template), now or as soon
    /// as it arrives; `"next"` and `"prev"` move its selection by a row, as ↓ and ↑ would, wherever
    /// the focus is.
    Select {
        select: String,
        #[serde(rename = "in")]
        of: String,
    },
    /// Change the style of the list at the focused editor's caret, all its siblings at once:
    /// `next` goes number → letter → roman → bullet.
    ListStyle { list_style: String },
    /// Show tab `tab` of the tabs node `of`, and move the focus into it.
    ShowTab { tab: usize, of: String },
    Theme { theme: String },
    Append { append: String, value: Value },
    /// With `for_ms`, the write lasts that long (see `Msg::Write`).
    Put {
        put: String,
        value: Value,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        for_ms: Option<u64>,
    },
    /// With `where` (a template, filled like `value`), every row of the array entry whose fields
    /// match all of it, wherever the focus is: `{"remove": "files", "where": {"id": "{store.doomed}"}}`.
    Remove {
        remove: String,
        #[serde(default, rename = "where", skip_serializing_if = "Option::is_none")]
        matching: Option<Value>,
    },
    /// Flip a true-or-false field of the focused list's or tree's selected row, in the store entry
    /// it shows (a missing field becomes true): a checkbox. `store.zen` flips a store entry, or a
    /// path into one, instead.
    Toggle { toggle: String },
    /// A message that shows for a while (`ms`, default 3000) in the corner, in a `tone`. A
    /// template, like `copy`.
    Toast {
        toast: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        tone: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        ms: Option<u64>,
    },
    /// Put text on the system clipboard (through the terminal, OSC 52). A template over the
    /// selected row, `store` and `$self`, like the store actions.
    Copy { copy: String },
    /// Ask the app that embeds the screen to do something (`Host::act`): `args` are templates, as
    /// in the store actions. The answer goes in `$log`; a failure shows on the status line. With
    /// `wait`, keys typed meanwhile wait until it has answered and the host sources it refreshes
    /// have landed, then go in order (for an act that closes or opens what the next key acts on).
    Host {
        host: String,
        #[serde(default, skip_serializing_if = "Value::is_null")]
        args: Value,
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        wait: bool,
    },
    Do {
        #[serde(rename = "do")]
        steps: Vec<Action>,
    },
}

/// How a picture fills its node: whole inside it (`contain`, the default) or covering it.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Fit {
    #[default]
    Contain,
    Cover,
}

impl Node {
    /// Whether row `r` (`v`) can't be selected: its variant is in the list's `skip`.
    pub fn skips(&self, v: &Value) -> bool {
        match &self.kind {
            Kind::List { rows: Rows { variant: Some(p), skip, .. }, .. } | Kind::Tree { rows: Rows { variant: Some(p), skip, .. }, .. } if !skip.is_empty() => {
                skip.contains(&scalar(lookup(v, p)))
            }
            _ => false,
        }
    }

    pub fn children(&self) -> &[Node] {
        match &self.kind {
            Kind::Col { children, .. } | Kind::Row { children, .. } | Kind::Grid { children, .. } | Kind::Stack { children } | Kind::Tabs { children, .. } => children,
            _ => &[],
        }
    }

    pub fn children_mut(&mut self) -> Option<&mut Vec<Node>> {
        match &mut self.kind {
            Kind::Col { children, .. } | Kind::Row { children, .. } | Kind::Grid { children, .. } | Kind::Stack { children } | Kind::Tabs { children, .. } => Some(children),
            _ => None,
        }
    }

    /// Which way it scrolls, if it does: down (true) for a `col`, `grid` or `each`, across
    /// (false) for a `row` or a `row: true` each.
    pub fn scrolls_down(&self) -> Option<bool> {
        if !self.scroll {
            return None;
        }
        match &self.kind {
            Kind::Col { .. } | Kind::Grid { .. } => Some(true),
            Kind::Row { .. } => Some(false),
            Kind::Each { row, .. } => Some(!row),
            _ => None,
        }
    }

    /// How many to a line a list, tree or grid lays out (see `state::per_line`).
    pub fn cols(&self) -> Option<&Cols> {
        match &self.kind {
            Kind::Grid { cols, .. } => Some(cols),
            _ => self.rows()?.cols.as_ref(),
        }
    }

    /// How a list or a tree draws its rows.
    pub fn rows(&self) -> Option<&Rows> {
        match &self.kind {
            Kind::List { rows, .. } | Kind::Tree { rows, .. } => Some(rows),
            _ => None,
        }
    }

    /// The path that names a row of a list, tree or table (`key`, default `id`).
    pub fn row_key(&self) -> &str {
        self.rows().and_then(|r| r.key.as_deref()).unwrap_or("id")
    }

    /// The filter a list, table or tree has: the bind its query text is read from.
    pub fn filter(&self) -> Option<&str> {
        match &self.kind {
            Kind::List { rows, .. } | Kind::Tree { rows, .. } => rows.filter.as_deref(),
            Kind::Table { filter, .. } => filter.as_deref(),
            _ => None,
        }
    }

    /// Lists, tables, trees, tabs and editors with an id take focus.
    pub fn focusable(&self) -> bool {
        self.id.is_some() && (matches!(self.kind, Kind::List { .. } | Kind::Table { .. } | Kind::Tree { .. } | Kind::Tabs { .. } | Kind::Button { .. }) || self.field().is_some())
    }

    /// The component's name, as written in `type`.
    pub fn kind_name(&self) -> &'static str {
        match &self.kind {
            Kind::Col { .. } => "col",
            Kind::Row { .. } => "row",
            Kind::Grid { .. } => "grid",
            Kind::Stack { .. } => "stack",
            Kind::Button { .. } => "button",
            Kind::Spinner { .. } => "spinner",
            Kind::Toasts { .. } => "toasts",
            Kind::Each { .. } => "each",
            Kind::Text { .. } => "text",
            Kind::List { .. } => "list",
            Kind::Tree { .. } => "tree",
            Kind::Rule { .. } => "rule",
            Kind::Table { .. } => "table",
            Kind::Sparkline { .. } => "sparkline",
            Kind::Chart { .. } => "chart",
            Kind::Bars { .. } => "bars",
            Kind::Gauge { .. } => "gauge",
            Kind::Big { .. } => "big",
            Kind::Editor { .. } => "editor",
            Kind::Input { .. } => "input",
            Kind::Tabs { .. } => "tabs",
            Kind::Plot { .. } => "plot",
            Kind::Image { .. } => "image",
            Kind::Svg { .. } => "svg",
            Kind::Dot { .. } => "dot",
            Kind::Map { .. } => "map",
        }
    }

    /// An editor or an input: the text component's settings.
    pub fn field(&self) -> Option<Field<'_>> {
        match &self.kind {
            Kind::Editor { text, doc, placeholder, syntax, readonly, tab, tasks, caret, links, ordered } => Some(Field {
                seed: text,
                doc: doc.as_deref(),
                placeholder: placeholder.as_deref(),
                line: false,
                markdown: syntax.as_deref() == Some("markdown"),
                number: false,
                required: false,
                readonly: *readonly,
                indents: matches!(tab.as_deref(), Some("indent" | "indent-lines")),
                indent_lines: tab.as_deref() == Some("indent-lines"),
                task_cycle: tasks.as_deref() == Some("cycle"),
                caret_end: caret.as_deref() == Some("end"),
                links,
                ordered,
            }),
            Kind::Input { text, placeholder, accept, required } => Some(Field {
                seed: text,
                doc: None,
                placeholder: placeholder.as_deref(),
                line: true,
                markdown: false,
                number: accept.as_deref() == Some("number"),
                required: *required,
                readonly: false,
                indents: false,
                indent_lines: false,
                task_cycle: false,
                caret_end: false,
                links: &[],
                ordered: &[],
            }),
            _ => None,
        }
    }

    /// Like `walk`, but only into what's shown: nodes `shown` passes, and the shown child of each
    /// tabs node (`tab` gives its index).
    pub fn walk_shown<'a>(&'a self, tab: &dyn Fn(&Node) -> usize, shown: &dyn Fn(&Node) -> bool, out: &mut Vec<&'a Node>) {
        if !shown(self) {
            return;
        }
        out.push(self);
        match &self.kind {
            Kind::Tabs { .. } => {
                if let Some(c) = self.page(tab(self)) {
                    c.walk_shown(tab, shown, out);
                }
            }
            _ => {
                for c in self.children() {
                    c.walk_shown(tab, shown, out);
                }
            }
        }
    }

    pub fn walk<'a>(&'a self, out: &mut Vec<&'a Node>) {
        out.push(self);
        for c in self.children() {
            c.walk(out);
        }
    }

    pub fn find(&self, id: &str) -> Option<&Node> {
        let mut all = Vec::new();
        self.walk(&mut all);
        all.into_iter().find(|n| n.id.as_deref() == Some(id))
    }

    /// The templates it fills from its bound value: its text, a button's label, tabs' titles
    /// and their bar's lead and trail, its title.
    pub fn templates(&self) -> impl Iterator<Item = &str> {
        let own: Vec<&str> = match &self.kind {
            Kind::Text { text, .. } => vec![text],
            Kind::Button { label } => vec![label],
            Kind::Tabs { tabs, lead, trail, .. } => tabs.iter().map(String::as_str).chain(lead.as_deref()).chain(trail.as_deref()).collect(),
            _ => vec![],
        };
        own.into_iter().chain(self.title.as_deref())
    }

    /// The page tabs show at `tab` (held to the last tab): its child there, if it has one.
    pub fn page(&self, tab: usize) -> Option<&Node> {
        match &self.kind {
            Kind::Tabs { tabs, children, .. } => children.get(tab.min(tabs.len().saturating_sub(1))),
            _ => None,
        }
    }

    /// The node at `part` of one of its rows: in a list's or tree's `row` template by its path
    /// (`0.2`), in a table's column's `cell` template by the column and then the path (`3.0`).
    pub fn row_part(&self, part: &str) -> Option<&Node> {
        match &self.kind {
            Kind::Table { columns, .. } => {
                let (col, rest) = part.split_once('.').unwrap_or((part, ""));
                columns.get(col.parse::<usize>().ok()?)?.cell.as_deref()?.at_path(rest)
            }
            _ => self.rows()?.row.as_deref()?.at_path(part),
        }
    }

    /// The node at `path` under this one, child indexes joined by dots (`0.2`; empty is this
    /// one), as a row's buttons are named.
    pub fn at_path(&self, path: &str) -> Option<&Node> {
        path.split('.').filter(|p| !p.is_empty()).try_fold(self, |n, k| n.children().get(k.parse::<usize>().ok()?))
    }

    /// The nodes from this one down to the node with this id, both included; empty when there
    /// is none.
    pub fn path_to(&self, id: &str) -> Vec<&Node> {
        if self.id.as_deref() == Some(id) {
            return vec![self];
        }
        for c in self.children() {
            let mut p = c.path_to(id);
            if !p.is_empty() {
                p.insert(0, self);
                return p;
            }
        }
        vec![]
    }

    /// Replace the node with this id; false when there is none.
    pub fn replace(&mut self, id: &str, with: &Node) -> bool {
        if self.id.as_deref() == Some(id) {
            *self = with.clone();
            return true;
        }
        self.children_mut().is_some_and(|cs| cs.iter_mut().any(|c| c.replace(id, with)))
    }
}

/// A list's row template for row `item`, `at` (index, count): filled as an `each` instance is,
/// with every id taken off, since the row takes the presses and the focus for all of it. Its
/// buttons keep their `click`, which a press on one runs on the row (`Msg::Press`).
pub fn row_instance(template: &Node, item: &Value, at: (usize, usize)) -> Node {
    fn bare(n: &mut Node) {
        n.id = None;
        if !matches!(n.kind, Kind::Button { .. }) {
            n.click = None;
        }
        if let Some(cs) = n.children_mut() {
            cs.iter_mut().for_each(bare);
        }
    }
    let mut n = instance(template, item, at);
    bare(&mut n);
    n
}

impl Rows {
    /// Whether each row is as tall as what it shows (its template's `size` is `fit`).
    pub fn fits(&self) -> bool {
        self.row.as_ref().and_then(|r| r.size.as_ref()).is_some_and(|s| s.measure() == Measure::Fit)
    }

    /// How many cells tall a row is: its template's `size` in cells, else `lines`, else one.
    pub fn height(&self) -> u16 {
        match self.row.as_ref().and_then(|r| r.size.as_ref()).map(Size::measure) {
            Some(Measure::Cells(c)) => c.max(1),
            _ => self.lines.unwrap_or(1).max(1),
        }
    }
}

/// What a tree shows before a row: its depth (two cells a level) and its fold glyph, `▾` open,
/// `▸` folded, or the tree's `leaf` (`· ` unless it says) when nothing is under it.
pub fn fold_lead<'a>(row: &Value, leaf: Option<&'a str>) -> (usize, &'a str) {
    let depth = row["$depth"].as_u64().unwrap_or(0) as usize;
    let glyph = match (row["$kids"].as_u64().unwrap_or(0) > 0, row["$open"].as_bool().unwrap_or(false)) {
        (true, true) => "▾ ",
        (true, false) => "▸ ",
        _ => leaf.unwrap_or("· "),
    };
    (depth, glyph)
}

/// A template node for one item of an `each` (or a list's row), `index` of `count` (from 0):
/// every `{$item}` and `{$item.path}` in its strings filled from the item (with a filter as any
/// placeholder takes: `{$item.side|me=end;*=start}`) but those in a template inside it (a list's
/// `row`, an `each`'s `template`, which have their own items), `{$index}` and
/// `{$count}` from where it is, the rest left as they are. A string filled whole is read again
/// as whatever the field takes, so `"size": "{$item.h}"` and a float's `"y": "{$item.start}"`
/// come from data.
pub fn instance(template: &Node, item: &Value, (index, count): (usize, usize)) -> Node {
    fn fill_item(s: &str, item: &Value) -> String {
        let mut out = String::new();
        let mut rest = s;
        while let Some(i) = rest.find("{$item") {
            let Some(j) = rest[i..].find('}') else { break };
            let inner = &rest[i + 1..i + j];
            let after = &inner["$item".len()..];
            // A path into the item, and a filter as any placeholder takes (`|me=end;*=start`).
            let (path, filter) = match after.split_once('|') {
                Some((p, f)) => (p, Some(f)),
                None => (after, None),
            };
            if !path.is_empty() && !path.starts_with('.') {
                // `{$items}` or the like: not ours.
                out.push_str(&rest[..i + j + 1]);
            } else {
                let path = path.strip_prefix('.').unwrap_or(path);
                let value = scalar(if path.is_empty() { Some(item) } else { lookup(item, path) });
                out.push_str(&rest[..i]);
                out.push_str(&filter.map_or(value.clone(), |f| picked(f, &value)));
            }
            rest = &rest[i + j + 1..];
        }
        out.push_str(rest);
        out
    }
    fn walk(v: &mut Value, item: &Value, at: &(String, String)) {
        match v {
            Value::String(s) if s.contains("{$") => {
                if s.contains("{$item") {
                    *s = fill_item(s, item);
                }
                *s = s.replace("{$index}", &at.0).replace("{$count}", &at.1);
            }
            Value::Array(a) => a.iter_mut().for_each(|x| walk(x, item, at)),
            // A list's `row` and a nested `each`'s `template` are templates of their own: their
            // `$item` is their rows', filled when they're drawn, not this one's.
            Value::Object(m) => m.iter_mut().filter(|(k, v)| !(v.is_object() && (*k == "row" || *k == "template"))).for_each(|(_, x)| walk(x, item, at)),
            _ => {}
        }
    }
    let mut v = serde_json::to_value(template).unwrap_or_default();
    walk(&mut v, item, &(index.to_string(), count.to_string()));
    serde_json::from_value(v).unwrap_or_else(|_| template.clone())
}

/// One run of a filled template: text, its style (a spec like `accent+b`, from `<accent+b>`), the
/// sign of a `{±x}` number, a tab (the rest of the line is right-aligned) or a fill character
/// (`{*─}`: repeat to the end of the line).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Seg {
    pub text: String,
    pub style: Option<String>,
    pub sign: Option<bool>,
    pub tab: bool,
    pub fill: Option<char>,
}

/// A template filled from `v`, as styled runs. The language:
///
/// - `{path}` a value (`{a.b}`, `{rows.0}`; `{.}` the value itself); `{{` is a literal brace.
/// - `{±path}` a value marked with its number's sign, for the view to colour.
/// - `{path|a=x;b=y;*=z}` maps the value (`*` is anything else); the result may carry styles and
///   `$` stands for the value. `{path|?then}` is `then` when the value isn't empty, `{path|!else}`
///   when it is. `{path|markup}` reads the value's own `<style>` runs (values are plain text
///   otherwise, so data can't restyle the screen).
/// - `<spec>` … `</>` a style: theme tokens or colours, `on-<colour>` for the background, and
///   `b` `d` `i` `u` `r` `s` (bold, dim, italic, underline, reverse, strike), joined by `+`.
///   Inside a mapped or `|markup` value a style layers on the one around it (a `<tag>` in a bold
///   title stays bold); `<=spec>` replaces it instead.
/// - a tab right-aligns the rest of the line; `{*─}` fills the line with `─`.
pub fn segments(template: &str, v: &Value) -> Vec<Seg> {
    let mut out = Vec::new();
    let mut cur: Option<String> = None;
    let mut rest = template;
    while !rest.is_empty() {
        let Some(i) = rest.find('{') else {
            markup(rest, &mut cur, &mut out);
            break;
        };
        markup(&rest[..i], &mut cur, &mut out);
        if rest[i..].starts_with("{{") {
            push(&mut out, "{", cur.clone(), None);
            rest = &rest[i + 2..];
            continue;
        }
        let Some(j) = rest[i..].find('}') else {
            push(&mut out, &rest[i..], cur.clone(), None);
            break;
        };
        let inner = &rest[i + 1..i + j];
        rest = &rest[i + j + 1..];
        let base = cur.clone();
        if let Some(c) = inner.strip_prefix('*') {
            out.push(Seg { fill: c.chars().next().or(Some(' ')), style: cur.clone(), ..Seg::default() });
            continue;
        }
        let (signed, inner) = match inner.strip_prefix('±') {
            Some(x) => (true, x),
            None => (false, inner),
        };
        let (path, filter) = match inner.split_once('|') {
            Some((p, f)) => (p, Some(f)),
            None => (inner, None),
        };
        // `{path:11}` fits the result to 11 cells; `{path:>11}` right-aligns it.
        let (path, width) = match path.rsplit_once(':') {
            Some((p, w)) => match w.strip_prefix('>').unwrap_or(w).parse::<usize>() {
                Ok(n) => (p, Some((n, w.starts_with('>')))),
                Err(_) => (path, None),
            },
            None => (path, None),
        };
        let start = out.len();
        let value = scalar(lookup(v, path));
        match filter {
            None => {
                let sign = signed.then(|| number(&value).map(|n| n >= 0.0)).flatten();
                push(&mut out, &value, cur.clone(), sign);
            }
            Some("markup") => markup_in(&value, base.as_deref(), &mut out),
            Some(f) => markup_in(&picked(f, &value), base.as_deref(), &mut out),
        }
        if let Some((n, right)) = width {
            let mine = out.split_off(start);
            out.extend(fit(mine, n, right));
        }
    }
    out.retain(|s| !s.text.is_empty() || s.tab || s.fill.is_some());
    out
}

/// What a placeholder's filter makes of its value, as template text (markup and all): `?then $`
/// only when it's set, `!otherwise` only when it isn't, or a map `a=x;b=y;*=z`; `$` is the value.
fn picked(filter: &str, value: &str) -> String {
    if let Some(then) = filter.strip_prefix('?') {
        return if value.is_empty() { String::new() } else { then.replace('$', value) };
    }
    if let Some(other) = filter.strip_prefix('!') {
        return if value.is_empty() { other.to_string() } else { String::new() };
    }
    let (mut hit, mut any) = (None, None);
    for arm in filter.split(';') {
        if let Some((k, x)) = arm.split_once('=') {
            if k == value {
                hit = Some(x);
            } else if k == "*" {
                any = Some(x);
            }
        }
    }
    hit.or(any).unwrap_or("").replace('$', value)
}

fn push(out: &mut Vec<Seg>, text: &str, style: Option<String>, sign: Option<bool>) {
    if !text.is_empty() {
        out.push(Seg { text: text.to_string(), style, sign, ..Seg::default() });
    }
}

/// A value's own styles, layered on `base` (the style around the placeholder).
fn markup_in(text: &str, base: Option<&str>, out: &mut Vec<Seg>) {
    let mut cur = base.map(str::to_string);
    markup_with(text, &mut cur, base, out);
}

/// Literal template text: `<spec>` and `</>` switch the style, a tab splits the line.
fn markup(text: &str, cur: &mut Option<String>, out: &mut Vec<Seg>) {
    markup_with(text, cur, None, out);
}

fn markup_with(text: &str, cur: &mut Option<String>, base: Option<&str>, out: &mut Vec<Seg>) {
    let mut rest = text;
    loop {
        // `<<` is a literal `<`.
        if let Some(i) = rest.find("<<").filter(|i| rest.find('<') == Some(*i)) {
            plain(&rest[..i], cur, out);
            push(out, "<", cur.clone(), None);
            rest = &rest[i + 2..];
            continue;
        }
        let tag = rest.find('<').and_then(|i| {
            let j = rest[i..].find('>')?;
            let spec = &rest[i + 1..i + j];
            let ok = spec == "/" || (!spec.is_empty() && spec.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '+' | '-' | '#' | '_' | '=' | '.')));
            ok.then_some((i, j, spec))
        });
        let upto = tag.map(|(i, ..)| i).unwrap_or(rest.len());
        plain(&rest[..upto], cur, out);
        let Some((i, j, spec)) = tag else { break };
        *cur = match (spec, base) {
            ("/", _) => base.map(str::to_string),
            (s, _) if s.starts_with('=') => Some(s[1..].to_string()),
            (s, Some(b)) => Some(format!("{b}+{s}")),
            (s, None) => Some(s.to_string()),
        };
        rest = &rest[i + j + 1..];
    }
}

/// Text without tags in the current style; a tab splits the line.
fn plain(text: &str, cur: &Option<String>, out: &mut Vec<Seg>) {
    for (k, part) in text.split('\t').enumerate() {
        if k > 0 {
            out.push(Seg { tab: true, ..Seg::default() });
        }
        push(out, part, cur.clone(), None);
    }
}

/// A placeholder's runs fitted to `width` cells: cut with an ellipsis, or padded with spaces on
/// the right (on the left with `right`).
fn fit(segs: Vec<Seg>, width: usize, right: bool) -> Vec<Seg> {
    let cells = |t: &str| unicode_width::UnicodeWidthStr::width(t);
    let total: usize = segs.iter().map(|s| cells(&s.text)).sum();
    let style = segs.first().and_then(|s| s.style.clone());
    if total <= width {
        let pad = Seg { text: " ".repeat(width - total), style, ..Seg::default() };
        return if right { std::iter::once(pad).chain(segs).collect() } else { segs.into_iter().chain(std::iter::once(pad)).collect() };
    }
    let mut out = Vec::new();
    let mut room = width.saturating_sub(1);
    for mut s in segs {
        if room == 0 {
            break;
        }
        let mut kept = String::new();
        for c in s.text.chars() {
            let w = cells(c.encode_utf8(&mut [0; 4]));
            if w > room {
                room = 0;
                break;
            }
            room -= w;
            kept.push(c);
        }
        s.text = kept;
        out.push(s);
    }
    if width > 0 {
        let style = out.last().and_then(|s| s.style.clone()).or(style);
        out.push(Seg { text: "…".into(), style, ..Seg::default() });
    }
    out
}

/// Whether a template line shows: it has no placeholders, or at least one fills to something.
/// A line made only of conditional parts that all came out empty is left out, so optional
/// details don't leave gaps.
pub fn shows(template: &str, v: &Value) -> bool {
    let mut any = false;
    let mut rest = template;
    while let Some(i) = rest.find('{') {
        if rest[i..].starts_with("{{") {
            rest = &rest[i + 2..];
            continue;
        }
        let Some(j) = rest[i..].find('}') else { break };
        let ph = &rest[i..i + j + 1];
        rest = &rest[i + j + 1..];
        if ph.starts_with("{*") {
            continue;
        }
        any = true;
        if segments(ph, v).iter().any(|g| !g.text.is_empty()) {
            return true;
        }
    }
    !any
}

/// Only the `{path}` placeholders filled, nothing else read: for markup of other kinds (SVG),
/// where `<g>` is an element, not a style.
pub fn fill_raw(template: &str, v: &Value) -> String {
    let mut out = String::new();
    let mut rest = template;
    while let Some(i) = rest.find('{') {
        out.push_str(&rest[..i]);
        if rest[i..].starts_with("{{") {
            out.push('{');
            rest = &rest[i + 2..];
            continue;
        }
        let Some(j) = rest[i..].find('}') else { break };
        out.push_str(&scalar(lookup(v, &rest[i + 1..i + j])));
        rest = &rest[i + j + 1..];
    }
    out.push_str(rest);
    out
}

/// A template filled as plain text (styles dropped, a tab as `\t`).
pub fn fill(template: &str, v: &Value) -> String {
    segments(template, v)
        .into_iter()
        .map(|s| if s.tab { "\t".to_string() } else { s.text })
        .collect()
}

/// The number in a cell's text: `-1,234.5`, `+4.2%`, `$12k` → -1234.5, 4.2, 12.
pub fn number(s: &str) -> Option<f64> {
    let t: String = s.chars().filter(|c| c.is_ascii_digit() || matches!(c, '-' | '.' | '+')).collect();
    t.parse().ok()
}

/// How full a `gauge` is, 0 to 1: its `value` filled from `v`, over `of` (a number, or a
/// template filled from `v`; default 1).
pub fn gauge_ratio(value: &str, of: Option<&Value>, v: &Value) -> f64 {
    let of = match of {
        Some(Value::String(t)) => number(&fill(t, v)),
        Some(o) => o.as_f64(),
        None => Some(1.),
    };
    let r = number(&fill(value, v)).unwrap_or(0.) / of.unwrap_or(1.);
    if r.is_finite() { r.clamp(0., 1.) } else { 0. }
}

/// What a `gauge` says: its `label` filled from `v`, else how full it is in percent.
pub fn gauge_label(value: &str, of: Option<&Value>, label: Option<&str>, v: &Value) -> String {
    label.map(|l| fill(l, v)).unwrap_or_else(|| format!("{:.0}%", gauge_ratio(value, of, v) * 100.))
}

/// A dotted path into a value (`items`, `a.b`, `rows.0`); `.` or empty is the value itself.
pub fn lookup<'a>(v: &'a Value, path: &str) -> Option<&'a Value> {
    if path.is_empty() || path == "." {
        return Some(v);
    }
    path.split('.').try_fold(v, |v, k| match v {
        Value::Object(m) => m.get(k),
        Value::Array(a) => k.parse::<usize>().ok().and_then(|i| a.get(i)),
        _ => None,
    })
}

pub fn scalar(v: Option<&Value>) -> String {
    match v {
        None | Some(Value::Null) => String::new(),
        Some(Value::String(s)) => s.clone(),
        Some(Value::Array(a)) => a.iter().map(|x| scalar(Some(x))).collect::<Vec<_>>().join(", "),
        Some(other) => other.to_string(),
    }
}


/// Whether `name` is a colour by itself (not a theme token): a name (`red`, `light-blue`,
/// `grey`), a palette index (`0`–`255`) or `#rrggbb`.
pub fn is_colour(name: &str) -> bool {
    let n = name.to_lowercase().replace([' ', '-', '_'], "").replace("bright", "light").replace("grey", "gray").replace("silver", "gray");
    let named = ["reset", "black", "red", "green", "yellow", "blue", "magenta", "cyan", "gray", "darkgray", "white", "lightblack", "lightwhite", "lightgray"];
    let light = ["red", "green", "yellow", "blue", "magenta", "cyan"];
    let hex = name.len() == 7 && name.starts_with('#') && name[1..].chars().all(|c| c.is_ascii_hexdigit());
    named.contains(&n.as_str()) || n.strip_prefix("light").is_some_and(|c| light.contains(&c)) || name.parse::<u8>().is_ok() || hex
}

