        assert_eq!(r.features.into_iter().collect::<Vec<_>>(), [("calt".into(), 0), ("cv01".into(), 1), ("liga".into(), 0), ("ss02".into(), 1)]);
        assert!(serde_json::from_value::<TypeRole>(json!({"features": {"ligatures": false}})).is_err());
